export function deepFixture(quote,page=1,qualification=quote,qualificationPage=page){
 if(qualification===quote&&qualificationPage===page)qualification=quote.slice(0,quote.lastIndexOf(' '));
 const evidence=[{quote,page,role:'supports',reason:'Directly states the measured result.'},{quote:qualification,page:qualificationPage,role:'qualifies',reason:'Bounds what can be concluded.'}];
 const highlight={quote,page,section:'Experimental findings',category:'result',explanation:'The measured result applies to these experiments, rather than all training objectives.',why:'Different optimization pressures must be distinguished.',title:'The training objective changes the interpretation of stable monitorability',interesting:'A stable average can coexist with degradation under direct concealment pressure.',mechanism:'Ordinary task rewards differ from explicit rewards for hiding intent; this is a proposed explanation.',uncertainty:'Only two training runs were studied. A causal role for token count is not established.',questions:['Does direct CoT pressure differ from ordinary RL here?','Could thinking-token changes explain the measured trend?','Which experiments bound the claim about RL?'],evidence};
 return {guide:{summary:'A bounded contrast between training objectives.',pipeline:'deep-v1',highlights:[highlight]},dossier:{centralQuestion:'When does training change monitorability?',priorExpectation:'Optimization may hide intent.',centralAnswer:'The objective and evaluation scope matter.',claims:[{title:highlight.title,claim:highlight.explanation,mechanism:highlight.mechanism,alternative:'Thinking-token usage may be associated with the trend.',uncertainty:highlight.uncertainty,evidence}]}};
}
